"""Versioned, signed, opaque pagination cursors for lineage queries.

A cursor captures the exact position within one filtered, depth-bounded
lineage result set and binds to every effective query parameter of the
request that produced it. Cursors are opaque to clients: the payload is
JSON wrapped in URL-safe Base64 and authenticated with HMAC-SHA256 using a
server-held secret, so a cursor cannot be forged or tampered with. Any
malformed, unsigned, wrong-version, or structurally invalid token is
rejected by the caller as a ``422 validation_error`` rather than trusted.
"""

from __future__ import annotations

import base64
import binascii
import hashlib
import hmac
import json
from typing import Any

#: Cursor format generation. Bump only when the claim set/encoding changes;
#: cursors carrying any other version are rejected as expired/unknown.
CURSOR_VERSION = "v1"

#: Claims whose exact values must match the request carrying the cursor, in
#: stable serialized order. ``offset`` is the position state itself.
_CLAIM_FIELDS = (
    "content_id",
    "direction",
    "max_depth",
    "min_depth",
    "relation_type",
    "limit",
    "offset",
)


class InvalidCursorError(ValueError):
    """The cursor token is absent, malformed, expired, or unverifiable."""


def _b64encode(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64decode(value: str) -> bytes:
    try:
        padding = "=" * (-len(value) % 4)
        return base64.urlsafe_b64decode(value + padding)
    except (binascii.Error, ValueError) as exc:
        raise InvalidCursorError("cursor is not valid base64") from exc


def _sign(secret: bytes, version: str, payload: str) -> bytes:
    return hmac.new(
        secret, f"{version}.{payload}".encode("utf-8"), hashlib.sha256
    ).digest()


def encode_cursor(secret: bytes, claims: dict[str, Any]) -> str:
    """Return an opaque, signed token for normalized pagination ``claims``."""
    payload = _b64encode(
        json.dumps(
            {field: claims[field] for field in _CLAIM_FIELDS},
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode("utf-8")
    )
    signature = _b64encode(_sign(secret, CURSOR_VERSION, payload))
    return f"{CURSOR_VERSION}.{payload}.{signature}"


def decode_cursor(secret: bytes, token: str) -> dict[str, Any]:
    """Verify and decode ``token``, returning its normalized claims dict.

    Raises :class:`InvalidCursorError` for an empty token, wrong number of
    segments, unknown version, bad Base64/JSON, a missing- or wrongly-typed
    claim, an out-of-range offset, or a signature that does not authenticate
    the payload.
    """
    if not isinstance(token, str) or not token:
        raise InvalidCursorError("cursor must not be empty")
    parts = token.split(".")
    if len(parts) != 3:
        raise InvalidCursorError("cursor has an invalid structure")
    version, payload, signature = parts
    if version != CURSOR_VERSION:
        raise InvalidCursorError("cursor uses an unknown or expired version")

    expected_signature = _b64encode(_sign(secret, version, payload))
    if not hmac.compare_digest(signature, expected_signature):
        raise InvalidCursorError("cursor signature is invalid")

    try:
        raw = _b64decode(payload)
        claims = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise InvalidCursorError("cursor payload is not valid JSON") from exc

    if not isinstance(claims, dict) or set(claims) != set(_CLAIM_FIELDS):
        raise InvalidCursorError("cursor payload has an invalid claim set")
    if not isinstance(claims["content_id"], str) or not claims["content_id"]:
        raise InvalidCursorError("cursor content_id is invalid")
    if claims["direction"] not in ("ancestors", "descendants"):
        raise InvalidCursorError("cursor direction is invalid")
    if not isinstance(claims["relation_type"], str | None) or (
        isinstance(claims["relation_type"], str)
        and claims["relation_type"] not in ("version_of", "derived_from")
    ):
        raise InvalidCursorError("cursor relation_type is invalid")
    for field in ("max_depth", "min_depth", "limit", "offset"):
        if not isinstance(claims[field], int) or isinstance(claims[field], bool):
            raise InvalidCursorError(f"cursor {field} must be an integer")
    if not (1 <= claims["max_depth"] <= 32):
        raise InvalidCursorError("cursor max_depth is out of range")
    if not (1 <= claims["min_depth"] <= claims["max_depth"]):
        raise InvalidCursorError("cursor min_depth is out of range")
    if not (1 <= claims["limit"] <= 100):
        raise InvalidCursorError("cursor limit is out of range")
    # An offset of 0 is never issued (a first page carries no cursor); a
    # negative offset is structurally invalid. No tight upper bound is
    # imposed: a wide graph can legitimately page past any small constant,
    # and a client cannot forge a large value without the server secret.
    if not isinstance(claims["offset"], int) or claims["offset"] < 1:
        raise InvalidCursorError("cursor offset must be a positive integer")
    return claims

"""Request and response schemas for the versioned JSON API.

There is deliberately no field capable of carrying content bytes: only digest
and metadata are accepted, so raw content cannot be persisted or logged.
"""

from __future__ import annotations

import base64
import binascii
import re
from datetime import datetime
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator

from provenance.canonical import canonical_json_bytes
from provenance.ed25519 import PUBLIC_KEY_LENGTH, SIGNATURE_LENGTH
from provenance.models import SUPPORTED_DIGEST_ALGORITHMS

_HEX64 = re.compile(r"^[0-9a-f]{64}$")


def _required_nonempty(value: str, field: str) -> str:
    cleaned = value.strip()
    if not cleaned:
        raise ValueError(f"{field} must not be empty")
    return cleaned


def _decode_base64(value: Any, field: str, expected_length: int) -> bytes:
    """Strictly decode standard Base64 (RFC 4648) and enforce a byte length.

    The URL/filename-safe alphabet, missing/incorrect padding, non-string
    input, and any decoded length other than ``expected_length`` are
    rejected.
    """
    if not isinstance(value, str):
        raise ValueError(f"{field} must be a Base64-encoded string")
    try:
        # validate=True rejects non-alphabet characters (including '-'/'_')
        # and bad padding; then re-encoding enforces canonical padding.
        raw = base64.b64decode(value, validate=True)
    except (binascii.Error, ValueError):
        raise ValueError(
            f"{field} must be standard Base64 (RFC 4648) with correct padding"
        ) from None
    if base64.b64encode(raw).decode("ascii") != value:
        raise ValueError(f"{field} must use canonical standard Base64 padding")
    if len(raw) != expected_length:
        raise ValueError(
            f"{field} must decode to exactly {expected_length} bytes"
            f" (got {len(raw)})"
        )
    return raw


class ActorCreate(BaseModel):
    id: str = Field(..., min_length=1, max_length=255)
    name: str = Field(..., min_length=1, max_length=4096)
    type: str = Field(..., min_length=1, max_length=64)

    @field_validator("id")
    @classmethod
    def _id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "id")

    @field_validator("name")
    @classmethod
    def _name_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "name")

    @field_validator("type")
    @classmethod
    def _type_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "type")


class ActorResponse(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: str
    name: str
    type: str
    created_at: datetime


class ContentCreate(BaseModel):
    digest_algorithm: str = Field(..., min_length=1, max_length=32)
    digest_hex: str = Field(..., min_length=1, max_length=128)
    media_type: str = Field(..., min_length=1, max_length=255)
    title: str | None = Field(default=None, max_length=4096)
    actor_id: str = Field(..., min_length=1, max_length=255)

    @field_validator("digest_algorithm")
    @classmethod
    def _algorithm_supported(cls, v: str) -> str:
        normalized = v.strip().lower()
        if normalized not in SUPPORTED_DIGEST_ALGORITHMS:
            supported = ", ".join(sorted(SUPPORTED_DIGEST_ALGORITHMS))
            raise ValueError(f"unsupported digest algorithm; supported: {supported}")
        return normalized

    @field_validator("digest_hex")
    @classmethod
    def _digest_is_sha256_hex(cls, v: str) -> str:
        # Normalize case so the same digest cannot be registered twice via
        # different casing; then enforce exactly 64 lowercase hex chars.
        normalized = v.strip().lower()
        if not _HEX64.fullmatch(normalized):
            raise ValueError("digest_hex must be exactly 64 hexadecimal characters")
        return normalized

    @field_validator("media_type")
    @classmethod
    def _media_type_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "media_type")

    @field_validator("actor_id")
    @classmethod
    def _actor_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "actor_id")

    @field_validator("title")
    @classmethod
    def _title_optional(cls, v: str | None) -> str | None:
        if v is None:
            return None
        cleaned = v.strip()
        return cleaned or None


class ContentResponse(BaseModel):
    model_config = ConfigDict(from_attributes=True)

    id: str
    digest_algorithm: str
    digest_hex: str
    media_type: str
    title: str | None
    actor_id: str
    created_at: datetime


class ContentListResponse(BaseModel):
    items: list[ContentResponse]
    count: int


class ContentLineageItem(ContentResponse):
    """A content reached by lineage traversal: the full public view plus depth.

    ``depth`` is the shortest number of lineage edges from the traversal
    origin; the origin itself is never included.
    """

    depth: int


class ContentLineageResponse(BaseModel):
    items: list[ContentLineageItem]
    #: Total number of items after relation/depth filtering, independent of
    #: pagination; not merely the size of the returned page.
    count: int
    #: Opaque server cursor for the next page, or null when the final page
    #: has been returned.
    next_cursor: str | None = None


class ClaimCreate(BaseModel):
    content_id: str = Field(..., min_length=1, max_length=80)
    actor_id: str = Field(..., min_length=1, max_length=255)
    claim_type: str = Field(..., min_length=1, max_length=128)
    #: Must be a JSON object; arrays, scalars, and null are rejected.
    payload: dict[str, Any]

    @field_validator("content_id")
    @classmethod
    def _content_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "content_id")

    @field_validator("actor_id")
    @classmethod
    def _actor_id_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "actor_id")

    @field_validator("claim_type")
    @classmethod
    def _claim_type_nonempty(cls, v: str) -> str:
        return _required_nonempty(v, "claim_type")

    @field_validator("payload")
    @classmethod
